import { normalizeText } from '@/domain/quickEntry';
import list from './banks.json';

/**
 * Brazilian banks and payment institutions, generated by `npm run banks` from the
 * `logos-bancos-br` package (Banco Central participant lists + Open Finance logos).
 * `id` is the COMPE code (or `ispb-…` for Pix-only institutions).
 */
export interface Bank {
  id: string;
  name: string;
  /** Logo file name (ISPB) under `/banks/`. */
  logo?: string;
  /** Card or brand names people search for ("Ourocard", "Hipercard"…). */
  aka?: string[];
}

export const BANKS: readonly Bank[] = list as Bank[];

const BY_ID = new Map(BANKS.map((bank) => [bank.id, bank]));

/** Shown first in the picker: the most used banks and card issuers. */
export const POPULAR_BANK_IDS = [
  '260', '341', '237', '001', '104', '033', '077', '336', '380', '323', '290', '208', '348', '536', '335', '623', '748', '756',
  '041', '422', '413', '468', '403', '197', '368', '374', '358', '396', '620',
];

export function bankById(id: string | null | undefined): Bank | undefined {
  return id ? BY_ID.get(id) : undefined;
}

export function bankLogoUrl(bank: Bank): string | null {
  return bank.logo ? `/banks/${bank.logo}.png` : null;
}

export function popularBanks(): Bank[] {
  return POPULAR_BANK_IDS.map((id) => BY_ID.get(id)).filter((bank): bank is Bank => Boolean(bank));
}

/** Accent-insensitive search by name, brand alias or COMPE code; prefix matches first. */
export function searchBanks(query: string, limit = 60): Bank[] {
  const q = normalizeText(query.trim());
  if (!q) return [...BANKS];
  const scored: { bank: Bank; score: number }[] = [];
  for (const bank of BANKS) {
    const names = [bank.name, ...(bank.aka ?? [])].map(normalizeText);
    let score = -1;
    if (bank.id === q || bank.id.replace(/^0+/, '') === q) score = 0;
    else if (names.some((n) => n.startsWith(q))) score = 1;
    else if (names.some((n) => n.split(/\s+/).some((word) => word.startsWith(q)))) score = 2;
    else if (names.some((n) => n.includes(q))) score = 3;
    if (score >= 0) scored.push({ bank, score: score * 2 + (POPULAR_BANK_IDS.includes(bank.id) ? 0 : 1) });
  }
  return scored
    .sort((a, b) => a.score - b.score || a.bank.name.localeCompare(b.bank.name))
    .slice(0, limit)
    .map((s) => s.bank);
}
